// Global error handler — MUST have 4 parameters for Express to treat it as one
app.use((err, req, res, next) => {
  // Log internally (use a real logger like pino or winston in production)
  console.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

